<?php
include_once 'global_CDC.php';
include 'dart_init.php';
$currentScript = basename ( $_SERVER ["SCRIPT_NAME"] );

exit();

// On various errors and failures, we'll use the status BAD update XML
$badXML = <<< EOT
<?xml version="1.0"?>
<deliverycomplete status="failed" code="0" retry="true" errmsg="XXX">
</deliverycomplete>
EOT;

exit();

// Since we can have multiple connections writing to the log file, we'll add a random code to log file entries.
$codeStr = generateRandomCode ( 6 );

$appJSON='{"dartsessionid":"9301","deliveryjson":{"invoice_list":[{"signtimestamp":"2012-02-21 08:40","invoice_item_list":[{"finalunitid":"132","edited":"false","finalqship":"0.5","finalunitprice":"41.5","lineid":"26489013"},{"finalunitid":"14","edited":"false","finalqship":"0.5","finalunitprice":"22.75","lineid":"26489014"},{"finalunitid":"109","edited":"false","finalqship":"0.25","finalunitprice":"10.9","lineid":"26489015"},{"finalunitid":"187","edited":"false","finalqship":"5","finalunitprice":"1.05","lineid":"26489016"},{"finalunitid":"169","edited":"false","finalqship":"0.5","finalunitprice":"20.5","lineid":"26489017"},{"finalunitid":"98","edited":"false","finalqship":"0.25","finalunitprice":"20.5","lineid":"26489018"},{"finalunitid":"542","edited":"false","finalqship":"6","finalunitprice":"0.65","lineid":"26489019"},{"finalunitid":"542","edited":"false","finalqship":"1","finalunitprice":"1.55","lineid":"26489020"},{"finalunitid":"542","edited":"false","finalqship":"3","finalunitprice":"0.8","lineid":"26489021"},{"finalunitid":"2","edited":"false","finalqship":"1","finalunitprice":"21.8","lineid":"26495359"},{"finalunitid":"2","edited":"false","finalqship":"0.5","finalunitprice":"21.6","lineid":"26495360"},{"finalunitid":"184","edited":"false","finalqship":"2","finalunitprice":"1.35","lineid":"26495366"},{"finalunitid":"25","edited":"false","finalqship":"1","finalunitprice":"21","lineid":"26489022"},{"finalunitid":"184","edited":"false","finalqship":"2","finalunitprice":"1.2","lineid":"26489023"},{"finalunitid":"14","edited":"false","finalqship":"0.25","finalunitprice":"26.9","lineid":"26489024"},{"finalunitid":"25","edited":"false","finalqship":"0.25","finalunitprice":"12.5","lineid":"26495361"},{"finalunitid":"664","edited":"false","finalqship":"1","finalunitprice":"-4.88","lineid":"26495367"},{"finalunitid":"299","edited":"false","finalqship":"10","finalunitprice":"0.35","lineid":"26489025"},{"finalunitid":"187","edited":"false","finalqship":"0.25","finalunitprice":"5.5","lineid":"26489026"},{"finalunitid":"299","edited":"false","finalqship":"15","finalunitprice":"0.25","lineid":"26489027"},{"finalunitid":"210","edited":"false","finalqship":"1","finalunitprice":"26.9","lineid":"26489028"},{"finalunitid":"2","edited":"false","finalqship":"1","finalunitprice":"11.7","lineid":"26489029"},{"finalunitid":"169","edited":"false","finalqship":"1","finalunitprice":"14.9","lineid":"26489030"},{"finalunitid":"185","edited":"false","finalqship":"1","finalunitprice":"10.5","lineid":"26489031"},{"finalunitid":"185","edited":"false","finalqship":"1","finalunitprice":"13.55","lineid":"26495362"},{"finalunitid":"185","edited":"false","finalqship":"1","finalunitprice":"14.75","lineid":"26489032"},{"finalunitid":"187","edited":"false","finalqship":"2","finalunitprice":"7.75","lineid":"26495363"},{"finalunitid":"80","edited":"false","finalqship":"1","finalunitprice":"34.35","lineid":"26495364"},{"finalunitid":"187","edited":"false","finalqship":"8","finalunitprice":"0.65","lineid":"26495365"},{"finalunitid":"187","edited":"false","finalqship":"3","finalunitprice":"1.16","lineid":"26489033"},{"finalunitid":"187","edited":"false","finalqship":"1","finalunitprice":"1.2","lineid":"26489034"},{"finalunitid":"133","edited":"false","finalqship":"0.25","finalunitprice":"69.98","lineid":"26489035"},{"finalunitid":"131","edited":"false","finalqship":"1","finalunitprice":"15.5","lineid":"26489036"},{"finalunitid":"25","edited":"false","finalqship":"0.25","finalunitprice":"12.3","lineid":"26489037"},{"finalunitid":"14","edited":"false","finalqship":"0.5","finalunitprice":"15.5","lineid":"26489038"},{"finalunitid":"310","edited":"false","finalqship":"2","finalunitprice":"7.45","lineid":"26489039"}],"lastupdatetime":"2012-02-21 06:21","saleid":"1470211","signatureimage":"","status":"DELIVERED"},{"signtimestamp":"2012-02-21 08:40","invoice_item_list":[{"finalunitid":"329","edited":"false","finalqship":"2","finalunitprice":"2.65","lineid":"26489114"},{"finalunitid":"322","edited":"false","finalqship":"4","finalunitprice":"4.55","lineid":"26489115"},{"finalunitid":"664","edited":"false","finalqship":"1","finalunitprice":"-0.47","lineid":"26495354"}],"lastupdatetime":"2012-02-21 06:21","saleid":"1470222","signatureimage":"","status":"DELIVERED"}],"delivery":{"signerid":"15613","locationid":"274","dark":"false","customernote":"","codinfo":{"checknum":"","cashamt":"","checkamt":"","creditcardamt":""},"signerinfo":{"lname":"","phone":"","fname":"","email":""}}},"userid":"4174"}';
dartLogging ( $currentScript, "jsondata=" . $appJSON, $codeStr );

// appJSON
if ($appJSON == FALSE || is_null ( $appJSON )) {
	dartLogging ( $currentScript, "    jsondata is FALSE or NULL", $codeStr );
	$badXML = preg_replace ( '/XXX/', $currentScript . ' : No jsondata supplied', $badXML );
	echo $badXML;
	exit ();
}

// Truncated appJSON - implies the connection was lost in midtransmission
if (! preg_match ( '/,"userid":"\d+"}$/', $appJSON )) {
	dartLogging ( $currentScript, "    jsondata is TRUNCATED", $codeStr );
	exit ();
}

// TODO CRC check

// Good to go...
$jd = json_decode ( $appJSON );

// Pull these out for easier reference
$locationID = $jd->deliveryjson->delivery->locationid;
$signerID = $jd->deliveryjson->delivery->signerid;
if ($signerID < 0) {
	$isDarkDrop = true;
	$signerID = DARK_STOP_ID;
} else {
	$isDarkDrop = false;
}

// Ignore printed invoice signers
if ($signerID != PRINTED_INVOICE_ID && $isDarkDrop == false) {
	// SIGNATURE IMAGE
	$filedir = DART_SIG_DIR . $jd->deliveryjson->delivery->locationid;
	if (! is_dir ( $filedir )) {
		if (! mkdir ( $filedir )) {
			dartLogging ( $currentScript, "    Could not create folder for locationID = " . $jd->deliveryjson->delivery->locationid, $codeStr );
			$badXML = preg_replace ( '/XXX/', $currentScript . ' : Could not create folder for locationID = ' . $jd->deliveryjson->delivery->locationid, $badXML );
			echo $badXML;
			exit ();
		}
	}
	// Convert the image to 24-bit and save
	foreach ( $jd->deliveryjson->invoice_list as $invoice ) {
		$file = $filedir . '/' . $invoice->saleid . ".png";
		
		// Create from the encoded string
		if (! $imgSrc = imagecreatefromstring ( base64_decode ( $invoice->signatureimage ) )) {
			dartLogging ( $currentScript, "    Could not create image from signatureimage data", $codeStr );
			$badXML = preg_replace ( '/XXX/', $currentScript . ' : Could not create image from signatureimage data', $badXML );
			echo $badXML;
			exit ();
		}
		$width = imagesx ( $imgSrc );
		$height = imagesy ( $imgSrc );
		
		// Make the new image
		if (! $imgDest = imagecreatetruecolor ( $width, $height )) {
			dartLogging ( $currentScript, "    Could not create new true color image", $codeStr );
			$badXML = preg_replace ( '/XXX/', $currentScript . ' : Could not create new true color image', $badXML );
			echo $badXML;
			exit ();
		}
		
		// Copy sent into new
		if (! imagecopy ( $imgDest, $imgSrc, 0, 0, 0, 0, $width, $height )) {
			dartLogging ( $currentScript, "    Could not copy source image to new image", $codeStr );
			$badXML = preg_replace ( '/XXX/', $currentScript . ' : Could not copy source image to new image', $badXML );
			echo $badXML;
			exit ();
		}
		
		// Write it out
		if (! imagepng ( $imgDest, $file )) {
			dartLogging ( $currentScript, "    Could not save png image", $codeStr );
			$badXML = preg_replace ( '/XXX/', $currentScript . ' : Could not save png image', $badXML );
			echo $badXML;
			exit ();
		}
	}
}

if ($jd->userid == DEBUG_USERID) {
	$resultXML = <<< EOT
<?xml version="1.0"?>
<deliverycomplete status="success">
</deliverycomplete>
EOT;
	echo $resultXML;
	exit ();
}

// Get the invoices marked as "delivered", which is code 2 for this stored procedure
$updateCode = 2;
$invXML = '';
$result = false;
try {
	$dbh = new PDO ( 'spdb', '', '' );
	$dbh->setAttribute ( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );
	
	// First check to see if there is a signer
	if ($signerID == 0) {
		// Add the signer
		$sql = "uspDARTAddSigner 0, $locationID, '" . preg_replace('/\'+/', '\'\'', trim ( $jd->deliveryjson->delivery->signerinfo->fname )) . "', ";
		$sql .= "'" . preg_replace('/\'+/', '\'\'', trim ( $jd->deliveryjson->delivery->signerinfo->lname )) . "', ";
		$sigEmail = trim ( $jd->deliveryjson->delivery->signerinfo->email );
		$sql .= ($sigEmail == '') ? 'null' : "'" . $sigEmail . "'";
		$sql .= ", 1, ";
		$sigPhone = formatPhone ( trim ( $jd->deliveryjson->delivery->signerinfo->phone ) );
		$sql .= ($sigPhone == '') ? 'null' : "'" . $sigPhone . "'";
		dartLogging ( $currentScript, "    uspDARTAddSigner sql=" . $sql, $codeStr );
		$stmt = $dbh->query ( $sql );
		$result = $stmt->fetch ( PDO::FETCH_ASSOC );
		$signerID = $result ['iUserID'];
		$stmt->closeCursor ();
	}
	
	// Prep for the XML version of invoice list for the stored procedure
	$invXML = "<ROOT>\n";
	foreach ( $jd->deliveryjson->invoice_list as $invoice )
		$invXML .= '<Rec rID="' . $invoice->saleid . '" dtDelTime="' . $invoice->signtimestamp . '.000"/>' . "\n";
	$invXML .= "</ROOT>";
	
	// Get the last update time according to the database
	$invTimesDB = array ();
	$stmt = $dbh->query ( "uspDARTCheckLastUpdate '" . $invXML . "'" );
	foreach ( $stmt->fetchAll ( PDO::FETCH_BOTH ) as $row ) {
		$lastUpdate = preg_replace ( '/(.*):\d{2}\.\d{3}$/', '$1', $row ['dtDartLastUpdated'] );
		$invTimesDB [$row ['iSaleID']] = $lastUpdate;
	}
	$stmt->closeCursor ();
	
	// Now mark the invoice as "delivered"
	$resultDelivered = $dbh->exec ( "uspDARTDelivered $updateCode, $signerID, '" . $invXML . "'" );
	
	// We need to build the list of invoices that have lastupdatetime values different between database and ipad
	$updateAtDeliveryFailXML = '';
	$saleDetailXML = '';
	foreach ( $jd->deliveryjson->invoice_list as $invoice ) {
		$getAllLines = false;
		if ($invoice->lastupdatetime != $invTimesDB [$invoice->saleid]) {
			$getAllLines = true;
			$updateAtDeliveryFailXML .= '<Rec rID="' . $invoice->saleid . '"/>' . "\n";
		}
		foreach ( $invoice->invoice_item_list as $line ) {
			if ($line->edited == "true" || $getAllLines == true) {
				$saleDetailXML .= '<Rec rID="' . $line->lineid . '" iUnitID="' . $line->finalunitid . '" fQty="' . $line->finalqship . '" mUnitPrice="' . $line->finalunitprice . '" iStatus= "' . '' . '"/>' . "\n";
			}
		}
	}
	
	// Now call the stored procedures, as needed, if my XML strings are not empty
	$resultUpdateChanges = true;
	if ($saleDetailXML != '') {
		$saleDetailXML = "<ROOT>\n" . $saleDetailXML . "</ROOT>";
		dartLogging ( $currentScript, "    saleDetailXML=" . $saleDetailXML, $codeStr );
		$resultUpdateChanges = $dbh->exec ( "uspDARTDeliveryCompleteUpdates '" . $saleDetailXML . "'" );
	}
	$resultDeliveryFail = true;
	if ($updateAtDeliveryFailXML != '') {
		$updateAtDeliveryFailXML = "<ROOT>\n" . $updateAtDeliveryFailXML . "</ROOT>";
		dartLogging ( $currentScript, "    updateAtDeliveryFailXML=" . $updateAtDeliveryFailXML, $codeStr );
		$resultDeliveryFail = $dbh->exec ( "uspDARTUpdateAtDeliveryFail '" . $updateAtDeliveryFailXML . "'" );
	}
	
	$dbh = null;
} catch ( PDOException $e ) {
	$errMsg = $e->getFile () . ' (' . $e->getLine () . ')' . $e->getMessage ();
	$errMsg .= "\ninvXML = " . $invXML;
	SP_ErrorLogging ( $errMsg, true, DART_ERROR_LOG );
	dartLogging ( $currentScript, "    Database error, see " . DART_ERROR_LOG, $codeStr );
	$badXML = preg_replace ( '/XXX/', $currentScript . ' : Database error, see ' . DART_ERROR_LOG . ' log', $badXML );
	echo $badXML;
	exit ();
}

if ($resultDelivered === false) {
	$errMsg = "uspDARTDelivered $updateCode, $signerID, $invXML returned FALSE";
	SP_ErrorLogging ( $errMsg, true, DART_ERROR_LOG );
	dartLogging ( $currentScript, "    Database error, see " . DART_ERROR_LOG, $codeStr );
	$badXML = preg_replace ( '/XXX/', $currentScript . ' : Database error, see ' . DART_ERROR_LOG . ' log', $badXML );
	echo $badXML;
	exit ();
}

if ($resultUpdateChanges === false) {
	$errMsg = "uspDARTDeliveryCompleteUpdates $saleDetailXML returned FALSE";
	SP_ErrorLogging ( $errMsg, true, DART_ERROR_LOG );
	dartLogging ( $currentScript, "    Database error, see " . DART_ERROR_LOG, $codeStr );
	$badXML = preg_replace ( '/XXX/', $currentScript . ' : Database error, see ' . DART_ERROR_LOG . ' log', $badXML );
	echo $badXML;
	exit ();
}

if ($resultDeliveryFail === false) {
	$errMsg = "uspDARTUpdateAtDeliveryFail $updateAtDeliveryFailXML returned FALSE";
	SP_ErrorLogging ( $errMsg, true, DART_ERROR_LOG );
	dartLogging ( $currentScript, "    Database error, see " . DART_ERROR_LOG, $codeStr );
	$badXML = preg_replace ( '/XXX/', $currentScript . ' : Database error, see ' . DART_ERROR_LOG . ' log', $badXML );
	echo $badXML;
	exit ();
}

// Call sendinvoices.php with the invoice list to generate the PDFs and send them out for non-PRINTED INVOICE
if ($signerID != PRINTED_INVOICE_ID) {
	$invoiceStr = '';
	foreach ( $jd->deliveryjson->invoice_list as $invoice )
		$invoiceStr .= " " . $invoice->saleid;
	pclose ( popen ( "start /B php sendinvoice.php$invoiceStr", "r" ) );
}

$resultXML = <<< EOT
<?xml version="1.0"?>
<deliverycomplete status="success">
</deliverycomplete>
EOT;
echo $resultXML;
dartLogging ( $currentScript, "    Success", $codeStr );
exit ();
?>